            bos.write(buf, 0, rd);
        }
        bos.flush();
        buf = bos.toByteArray();
        responseDump = new String(buf);
        inputStream.close();
        inputStream = new ByteArrayInputStream(buf);
    }
    parseResponse(envelope, inputStream);
    inputStream.close();
}

