        if (totalCalls != 1) {
            totalTime = totalTime + elapsedTime;
            minTime = Math.min(minTime, elapsedTime);
            maxTime = Math.max(maxTime, elapsedTime);
        } else {
            minTime = elapsedTime;
            maxTime = 0L;
        }
