public int[] solution(String S, int[] P, int[] Q) {
    int[] result = new int[P.length];
    int[] nums = new int[S.length()];
    for (int i = 0; i < S.length(); ++i) {
        switch (S.charAt(i)) {
            case 'A':
                nums[i] = 1;
                break;
            case 'C':
                nums[i] = 2;
                break;
            case 'G':
                nums[i] = 3;
                break;
            case 'T':
                nums[i] = 4;
                break;
            default:
                break;
        }
    }
    int[] pre = new int[4];
    int[] sum = new int[4];
    for (int i = 0; i < S.length(); ++i) {
        pre[nums[i] - 1] = 1;
        for (int j = 0; j < 4; ++j) {
            sum[j] = pre[j] + sum[j];
        }
        int start = P[i];
        int end = Q[i];
        // if start is 0, we just need to look for index end
        if (start == 0) {
            for (int n = 0; n < 4; n++) {
                if (sum[n] != 0) {
                    result[i] = n + 1;
                    break;
                }
            }
        } else {
            for (int n = 0; n < 4; n++) {
                // look for index > start and <= end
                if (sum[n] - pre[n] > 0 && sum[n] - pre[n] <= end - start + 1) {
                    result[i] = n + 1;
                    break;
                }
            }
        }
    }
    return result;
}

