public static void shuffle(int[] array) {
    if(random == null) random = new Random();
    for (int i = array.length - 1; i > 0; i--) {
        int swapWith = random.nextInt(i);
        int temp = array[i];
        array[i] = array[swapWith];
        array[swapWith] = temp;
    }
}

