            if(lIndex == l.length && rIndex == r.length) return;
            if(lIndex < l.length && (rIndex == r.length || l[lIndex] < r[rIndex])) {
                a[aIndex] = l[lIndex];
                mergeSub(a, aIndex + 1, l, lIndex + 1, r, rIndex);
            } else {
                a[aIndex] = r[rIndex];
