public static String camelCaser(String str) {
    String outputString = "";
    char currentChar = ' ';
    char prevChar = ' ';
    for (int i=0; i< str.length(); i++) {
        currentChar=str.charAt(i);
        if ( prevChar == '_'){
            outputString+= currentChar;
        }else{
            outputString+=currentChar;
        }
        prevChar = currentChar;
    }
    return outputString.replace("_","").toUpperCase();
}

