public int solution (int X, int [] A) {
    Set<Integer> leaves = new HashSet<>();
    int i = 0;
    do {
        leaves.add(A[i]);
        if(leaves.size() == X) return i;
        i++;
    } while(i < A.length);
    return -1;
}

