    BufferedInputStream in = new BufferedInputStream(new FileInputStream(src));
    byte[] read = new byte[128];
    int len = 128;
    while ((len = in.read(read)) > 0) out.write(read, 0, len);
    out.flush();
    out.close();
    in.close();
}

