        URLConnection conn = url.openConnection();
        conn.connect();
        is = conn.getInputStream();
        bm = BitmapFactory.decodeStream(is);
    } catch (IOException e) {
        Log.i(TAG, "Download of image failed: " + e.getMessage());
    } finally {
        if (is != null) {
            try {
                is.close();
            } catch (IOException e) {
            }
