    StringBuilder sb = new StringBuilder ();
    for (int i = 0; i < s.length() - 1; i++)
        sb.append(s.charAt(i * columns % (s.length() - 1)));
    sb.append(s.charAt(s.length() - 1));
    return sb.toString();
}

