        return 1;
    if (amount < 0 || checkFromIndex >= coins.length)
        return 0;
    return findCombinationsCount(amount - coins[checkFromIndex], coins, checkFromIndex) 
           + findCombinationsCount(amount, coins, checkFromIndex + 1);
}

