public static int solution (Integer number) {
    int maxGap = 0;
    int currentGap = 0;
    boolean counting = false;

for (char bit : Integer.toBinaryString(number).toCharArray()) {
        if (bit == '1') {
            if (currentGap != 0) {
                maxGap = Math.max(maxGap, currentGap);
                currentGap = 0;
            }
            counting = true;
        } else if (counting){
            currentGap++;
        }
    }
    return maxGap;
}

