            int result = 0;
            while (N > 0) {
                if ((N & 1) == 1)
                    result = Math.max (result, countZeros(N>>= 1));
                else 
                    N>>= 1;
            }
            return result;
        }

public int countZeros(int N) {
            int count = 0;
            while (N > 0 && (N & 1) != 1) {
                count ++;
                N >>= 1;
            }
            return count;
}

