private static int solution(int N) {
    int gap = 0;
    int length = 0;
    while (N > 0) {
        if ((N & 1) == 0)
            length++;
        else {
            gap = Math.max(gap, length);
            length = 0;
        }
        N >>= 1;
    }
    return gap;
}

