                    }
                }
                AssocView.write("EndOfMethod");
                AssocView.newLine();
                foundRead = false;
                foundWrite = false;
            }
            if (classWritten == true) {
                AssocView.write("EndOfClass");
                AssocView.newLine();
                classWritten = false;
            }
        }
        PC.close();
        AssocView.close();
    } catch (IOException e) {
