public int solution (int n) {
	int res = 0;
	while (n > 0) {
		if ((n & 1) == 1) {
			int temp = 0;
			int flag = 0;
			while (flag == 0) {
				if ((n & 1) != 1) {
					temp++;
					n >>>= 1;
				} else {
					flag = 1;
					n = 0;
				}
			}
			res = Math.max(res, temp);
		}
		n >>>= 1;
	}
	return res;
}

