                System.err.println("+--Param    : " + (String) sd.params.get(loop));
            }
        }
        throw ex;
    } finally {
        _statements.clear();
        conn.rollback();
        conn.clearWarnings();
        ConnectionFactoryProxy.getInstance().releaseConnection(conn);
    }
    return numRowsUpdated;
}

