        if (!folder.exists()) folder.mkdirs();
        File filename = new File(folder, file.getId() + "");
        IOUtils.copyLarge(stream, new FileOutputStream(filename));
        return file;
    } catch (IOException e) {
        throw new ServiceException("storage", e);
    }
}

