static int [] createArray (int size) {
    int [] result = new int [size];
    int limit = (size + 1) / 2;
    int start = 0, value = 0, idx = 0;
    do {
        for (int i = start;
        i < start + limit && idx < size; ++ i) result [idx ++] = value;
        start += limit;
        limit = (limit + 1) / 2;
        ++ value;
    } while (idx < size);
    return result;
}

func2:
static int[] createArray(int size) {
    int[] result = new int[size];
    int limit = size + 1;
    int start = 0;
    int value = 0, idx = 0;
    while (idx < size) {
        int range = limit / 2;
        for (int i = start; i < start + range && idx < size; i++) {
            result[idx++] = value;
        }
        start += range;
        limit /= 2;
        if (limit == 2) limit++;
        value++;
    }
    return result;
}

