public Node reverse(Node previous, Node current) {
    if (previous != null) {
        if (previous.equals(head)) {
            previous.setNext(null);
        }
        if (current != null) {
            Node temp = current.getNext();
            current.setNext(previous);
            return reverse(current, temp);
        } else {
            return head = previous;
        }
    }
    return null;
}

