        e.printStackTrace();
    } catch (MalformedContentNameStringException e) {
        System.out.println("Malformed name: " + args[CommonParameters.startArg] + " " + e.getMessage());
        e.printStackTrace();
    } catch (IOException e) {
        System.out.println("Cannot write file or read content. " + e.getMessage());
        e.printStackTrace();
    }
