public static String interleave(String you, String me) {
    int maxLength = Math.max(you.length(), me.length());
    String out = "";
    for (int i = 0; i < maxLength; i++) {
        if(i < you.length()) out += you.charAt(i);
        if(i < me.length()) out += me.charAt(i);
    }
    return out;
}

