private static int solution (int N) {
    int maxGap = 0;
    int oneIndex = -1;
    while (N > 0) { 
        int remainder = N % 2;
        if (remainder == 1 && oneIndex >= 0) {
            int zerosLen = oneIndex - 0;
            if (zerosLen > 0) {
                maxGap = Math.max (zerosLen, maxGap);
            }
            N = N / 2;
            oneIndex = 0;
        }
        else {
            oneIndex++;
            N = N / 2;
        }
    }
    return maxGap;
}

