        }
        queryString = queryString + "WHERE ";
        if (elementId != null) {
            queryString = queryString + this.getCallElementsSchemaAndTableName() + ".elementId = ? AND ";
        }
        if (contextName != null) {
            queryString = queryString + this.getCallElementsSchemaAndTableName() + ".context_name LIKE ? AND ";
