public static String getSHA1Digest(String inputStr) throws NoSuchAlgorithmException, UnsupportedEncodingException {
    MessageDigest md = null;
    byte[] sha1hash = null;
    md = MessageDigest.getInstance("SHA");
    sha1hash = new byte[40];
