            IOUtils.copyLarge(is, bos);
        } else {
            URLUtils.getResponse(getUrl(), getUserName(), getPassword(), bos, null);
        }
        bos.flush();
        bos.close();
        File listFile = new File(listFilePath);
        if (!listFile.exists()) {
            throw new IllegalStateException("The list file did not get created");
