public int solution(int X, int[] A) {
    BitSet bitSet = new BitSet();
    long sum = ((long) X * (X + 1)) / 2;
    long sumCheck = 0;
    for (int i=0; i< A.length; i++) {
        if (!bitSet.get(A[i])) { 
            sumCheck += A[i];
            bitSet.set(A[i]);
            if (sumCheck == sum) return i;
        }
    }
    return -1;
}

