    if (toFile.isDirectory()) toFile = new File(toFile, fromFile.getName());
    if (toFile.exists()) {
        if (!toFile.canWrite()) throw new IOException("FileCopy: " + "destination file is unwriteable: " + toFile.getCanonicalPath());
