public String postEvent(EventDocument eventDoc, Map attachments) {
    if (eventDoc == null || eventDoc.getEvent() == null) return null;
    if (jmsTemplate == null) {
        sendEvent(eventDoc, attachments);
        return eventDoc.getEvent().getEventId();
