        name += SEPARATOR + UNION_AND + SEPARATOR + (decimalPart.equals(decimalValZero) ? "zero" : processor.getName(decimalPart)) + SEPARATOR + SCALE.getName(-decimalPart.length());
    }

    return name;
}

