                jarOut.putNextEntry(o1);
                InputStream entryStream = jar.getInputStream(o1);
                IOUtils.copy(entryStream, jarOut);
                jarOut.closeEntry();
            }
        }
    }
    jarOut.finish();
    jarOut.close();
}

