        read = bufRead.read();
        while (read != -1) {
            bufWrite.write(read);
            offset += read;
            read = bufRead.read();
        }
        bufRead.close();
        bufWrite.close();
        ins.close();
        FileInputStream fs = new FileInputStream(path);
        retModel.read(fs, "");
    }
    return path;
