            if (key != null) {
                result.addHeader(key, val.get(0), val);
            } else {
                result.addHeader("Status", val.get(0), val);
            }
        }
        this.lastResult = result;
    } catch (IOException e) {
        throw new ConnectException(e);
    }
}

