        long fileOffset = outputOffset(header);
        for (int i = 0; i < srcFilePath.length; i++) {
            String sourceFileName = FileUtils.getFileName(srcFilePath[i]);
            long sourceFileSize = FileUtils.getFileSize(srcFilePath[i]);
