public String encryptToSHA(String info) {
    byte[] digesta = null;
    try {
        MessageDigest alga = MessageDigest.getInstance("SHA-1");
        alga.update(info.getBytes());
        digesta = alga.digest();
    } catch (NoSuchAlgorithmException e) {
        e.printStackTrace();
    }
    String rs = byte2hex(digesta);
    return rs;
}

