public static void shuffleArray (int [] array) {
    Random rand = new Random ();
    int n = array.length;
    while (n > 0) {
        int index = rand.nextInt (n);
        n--;
        int temp = array [n];
        array [n] = array [index];
        array [index] = temp;
    }
}

