public static int solution(Integer number) {
    int maxGap = 0;
    int gapCount = 0;
    number >>>= Integer.numberOfTrailingZeros(number);

while (number > 0) {
        if((number & 1) == 0) {
            gapCount++;
        } else {
            if(gapCount != 0) {
                maxGap = Math.max(maxGap, gapCount);
                gapCount = 0;
            }
        }
        number >>>= 1;
    }
    return maxGap;
}

