public int solution (int X, int [] A) {
    int count = 0;
    int sum = X * (X + 1) / 2;
    int A_sum = 0;
    for (int i = 0; i < A.length; i++) {
        if (A[i] <= X) {
            A_sum += A[i];
            count++;
        }
        if (A_sum == sum && count == X) 
            return i;
    } 
    return -1;
}

