public int solution(int X, int[] A) {
      int[] check = new int[X+1];
      int counter = 0;
      for(int i = 0; i < A.length; i++) {
        int tmp = A[i];
        if(tmp <= X && check[tmp] == 0) {
          check[tmp] = 1;
          counter++;
        }
        if(counter == X) return i;
      }
      return -1;
}

