                totalRead += numRead;
            }
        }
        re_buffer = ByteBuffer.wrap(temp_buffer);
        in.close();
    } catch (Exception e) {
        System.err.println("Could not read from temporary file into buffer.");
        System.err.println(e.getMessage());
        e.printStackTrace();
        return;
    }
