public static void bubbleSort (int [] numArray) {
    boolean sorted = false;
    int temp;
    while(!sorted) {
        sorted = true;
        for (int i = 0; i < numArray.length - 1; i++) {
            if (numArray[i] > numArray[i+1]) {
                temp = numArray[i];
                numArray[i] = numArray[i+1];
                numArray[i+1] = temp;
                sorted = false;
            }
        }
    }
}

