public int solution(int X, int[] A) {
    int target = IntStream.rangeClosed(1, X).sum();
    Set<Integer> set = new HashSet<>();
    int sum = 0;
    for (int i = 0; i < A.length; i++) {
        if (set.add(A[i])) sum += A[i];
        if (sum == target) return i;
    }
    return -1;
}

