public int[] zeroFront(int[] nums) {
    int count = 0;
    for(int i = 0; i < nums.length; i++) {
        if(nums[i] == 0) count++;
    }
    for(int i = 0; i < count; i++) {
        nums[i] = 0;
    }
    for(int i = count; i < nums.length; i++) {
        nums[i] = 1;
    }
    return nums;
}

