public static boolean isBalanced(String s) {
    if(s.length()%2 != 0)
        return false;

char[] chars = new char[s.length()];
    int i=0;
    for(char ch : s.toCharArray()){
        if(ch=='{' || ch=='[' || ch=='('){
            chars[i++] = ch;
        }
        if(ch=='}' || ch==']' || ch==')'){
            if(i==0 || Math.abs(ch-chars[--i])>2 ){
                return false;
            }
        }
    }
    return i==0;
}

