public int solution (int X, int[] A) {
    Set<Integer> set = new HashSet<>();
    int i = 0;
    while(set.size() != X && i < A.length) {
        if (A[i] <= X){
            set.add(A[i]);
        }
        i++;
    }
    return set.size() == X ? i - 1 : -1;
}

